v=$(sw_vers -productVersion); mj=${v%%.*}; mem=$(( $(sysctl -n hw.memsize) / 1073741824 )); free=$(df -k / | awk 'NR==2{print int($4/1048576)}'); hv=$(sysctl -n kern.hv_support 2>/dev/null); chip=$(sysctl -n machdep.cpu.brand_string); m(){ [ "$1" = 1 ] && echo ○ || echo ×; }; echo; echo '項目        教材  gm2   いまのMac'; printf 'macOS       %s    %s    %s\n' $(m $(( mj >= 15 ))) $(m $(( mj >= 15 ))) "macOS $v"; printf 'メモリ      %s    %s    %s\n' $(m $(( mem >= 8 ))) $(m $(( mem >= 16 ))) "$mem GB"; printf '仮想化      %s    %s    %s\n' $(m $(( hv == 1 ))) $(m $(( hv == 1 ))) "$( [ "$hv" = 1 ] && echo 使える || echo 使えないかもしれない)（$chip）"; printf '空き容量    %s    %s    %s\n' $(m $(( free >= 20 ))) $(m $(( free >= 50 ))) "$free GB"; echo
